const MAX_ATTEMPTS = 3;

/**
 * Creates an offline mutation queue.
 *
 * @param {Object} opts
 * @param {(mutation: any) => Promise<any>} opts.send   Posts a single mutation. Rejects on failure.
 * @param {Object} [opts.storage]                       localStorage-shaped: getItem/setItem/removeItem.
 * @param {() => boolean} [opts.isOnline]               Injected connectivity predicate.
 */
export function createQueue({ send, storage, isOnline = () => true }) {
  let nextId = 1;
  let pending = []; // FIFO of {id, mutation, attempts}
  let deadLetters = [];

  const persist = () => {
    if (!storage) return;
    storage.setItem(
      STORAGE_KEY,
      JSON.stringify({ nextId, pending, deadLetters })
    );
  };

  const load = () => {
    if (!storage) return;
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return;
    try {
      const state = JSON.parse(raw);
      if (Array.isArray(state.pending)) pending = state.pending;
      if (Array.isArray(state.deadLetters)) deadLetters = state.deadLetters;
      if (Number.isInteger(state.nextId)) nextId = state.nextId;
    } catch {
      // Corrupt state: start clean rather than crash.
    }
  };

  load();

  const recordFailure = (entry, err) => {
    entry.attempts += 1;
    if (entry.attempts >= MAX_ATTEMPTS) {
      deadLetters.push({
        id: entry.id,
        mutation: entry.mutation,
        attempts: entry.attempts,
        error: serializeError(err),
      });
      pending = pending.filter((p) => p.id !== entry.id);
    }
    persist();
  };

  const flush = async () => {
    while (pending.length > 0 && isOnline()) {
      const entry = pending[0];
      try {
        await send(entry.mutation);
        pending.shift(); // success: drop the head
        persist();
      } catch (err) {
        // Stop at first failure; failed entry and everything after stay persisted.
        recordFailure(entry, err);
        break;
      }
    }
  };

  return {
    async enqueue(mutation) {
      const entry = { id: nextId++, mutation, attempts: 0 };
      pending.push(entry);
      persist();
      if (isOnline()) {
        await flush();
      }
      return entry.id;
    },

    flush,

    goingOnline() {
      return flush();
    },

    isOnline,

    pending() {
      return pending.map(({ id, mutation, attempts }) => ({
        id,
        mutation,
        attempts,
      }));
    },

    deadLetters() {
      return deadLetters.map((d) => ({ ...d }));
    },
  };
}

function serializeError(err) {
  if (err instanceof Error) return { message: err.message };
  return { message: String(err) };
}
"})
