result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/offline-queue/test/queue.test.js", "content": "import { describe, it, expect, vi } from 'vitest';
import { createQueue } from '../src/queue.js';

const STORAGE_KEY = 'queue:v1';

function makeStorage() {
  const map = new Map();
  return {
    getItem: (k) => (map.has(k) ? map.get(k) : null),
    setItem: (k, v) => map.set(k, String(v)),
    removeItem: (k) => map.delete(k),
    _dump: () => JSON.parse(map.get(STORAGE_KEY)),
  };
}

// Scriptable send stub: each entry is either a value to resolve with
// or an Error to reject with. Consumed in FIFO order.
function scriptableSend(script) {
  const calls = [];
  const fn = vi.fn(async () => {
    calls.push(script.length);
    if (script.length === 0) return 'ok';
    const step = script.shift();
    if (step instanceof Error) throw step;
    return step;
  });
  fn.calls = calls;
  return fn;
}

describe('createQueue', () => {
  it('sends immediately when online', async () => {
    const send = scriptableSend(['ack']);
    const q = createQueue({ send, storage: makeStorage(), isOnline: () => true });
    await q.enqueue({ type: 'CREATE_POST', title: 'hi' });
    expect(send).toHaveBeenCalledTimes(1);
    expect(send.mock.calls[0][0]).toEqual({ type: 'CREATE_POST', title: 'hi' });
    expect(q.pending()).toHaveLength(0);
    expect(q.deadLetters()).toHaveLength(0);
  });

  it('persists when offline; flush drains in FIFO order', async () => {
    let online = false;
    const send = scriptableSend(['a1', 'a2', 'a3']);
    const q = createQueue({ send, storage: makeStorage(), isOnline: () => online });

    const id1 = await q.enqueue({ op: 'first' });
    const id2 = await q.enqueue({ op: 'second' });
    const id3 = await q.enqueue({ op: 'third' });

    // Monotonic ids
    expect([id1, id2, id3]).toEqual([1, 2, 3]);
    expect(send).not.toHaveBeenCalled();
    expect(q.pending().map((p) => p.mutation.op)).toEqual(['first', 'second', 'third']);

    online = true;
    await q.flush();

    expect(send).toHaveBeenCalledTimes(3);
    expect(send.mock.calls.map((c) => c[0].op)).toEqual(['first', 'second', 'third']);
    expect(q.pending()).toHaveLength(0);
  });

  it('stops at first failure mid-flush, leaving failed + rest persisted', async () => {
    let online = true;
    const send = scriptableSend([
      'ok',
      new Error('network down'),
      'never reached',
    ]);
    const storage = makeStorage();
    const q = createQueue({ send, storage, isOnline: () => online });

    await q.enqueue({ op: 'a' });
    await q.enqueue({ op: 'b' });
    await q.enqueue({ op: 'c' });

    online = true;
    await q.flush();

    expect(send).toHaveBeenCalledTimes(2); // a succeeded, b failed, c never attempted
    expect(q.pending().map((p) => p.mutation.op)).toEqual(['b', 'c']);
    expect(q.pending()[0].attempts).toBe(1);

    // State consistent on disk too
    const persisted = storage._dump();
    expect(persisted.pending.map((p) => p.mutation.op)).toEqual(['b', 'c']);
    expect(storage._dump().nextId).toBe(4);

    // Retry later succeeds for the remainder
    await q.flush();
    expect(send).toHaveBeenCalledTimes(3);
    expect(send.mock.calls[2][0].op).toBe('b');
    expect(q.pending()).toHaveLength(0);
  });

  it('promotes mutations to dead letters after 3 failed attempts', async () => {
    let online = true;
    const fail = () => Promise.reject(new Error('still down'));
    const send = vi.fn(fail);
    const q = createQueue({ send, storage: makeStorage(), isOnline: () => online });

    await q.enqueue({ op: 'doomed' }); // attempt 1 (immediate send)
    await q.flush(); // attempt 2
    await q.flush(); // attempt 3 -> dead letter

    expect(send).toHaveBeenCalledTimes(3);
    expect(q.pending()).toHaveLength(0);
    const dl = q.deadLetters();
    expect(dl).toHaveLength(1);
    expect(dl[0]).toMatchObject({
      id: 1,
      mutation: { op: 'doomed' },
      attempts: 3,
      error: { message: 'still down' },
    });
  });

  it('dead-lettered entries do not block the queue behind them', async () => {
    const fail = new Error('boom');
    const send = scriptableSend([fail, fail, fail, 'ok']);
    const q = createQueue({ send, storage: makeStorage() });

    await q.enqueue({ op: 'poison' });
    await q.flush(); // attempts 2
    await q.flush(); // attempt 3, poisoned to DLQ
    await q.enqueue({ op: 'fresh' }); // should send immediately

    expect(q.deadLetters().map((d) => d.mutation.op)).toEqual(['poison']);
    expect(q.pending()).toHaveLength(0);
  });

  it('rehydrates pending queue and dead letters from storage', async () => {
    const storage = makeStorage();
    storage.setItem(
      STORAGE_KEY,
      JSON.stringify({
        nextId: 42,
        pending: [
          { id: 40, mutation: { op: 'old-1' }, attempts: 0 },
          { id: 41, mutation: { op: 'old-2' }, attempts: 2 },
        ],
        deadLetters: [{ id: 39, mutation: { op: 'old-dead' }, attempts: 3 }],
      })
    );

    let online = false;
    const send = scriptableSend([]);
    const q = createQueue({ send, storage, isOnline: () => online });

    // Resumed state visible without any sends
    expect(send).not.toHaveBeenCalled();
    expect(q.pending().map((p) => p.mutation.op)).toEqual(['old-1', 'old-2']);
    expect(q.pending()[1].attempts).toBe(2);
    expect(q.deadLetters()[0].mutation.op).toBe('old-dead');

    // Ids continue monotonically from persisted counter
    const id = await q.enqueue({ op: 'new' });
    expect(id).toBe(42);
    expect(q.pending().map((p) => p.id)).toEqual([40, 41, 42]);

    // goingOnline triggers flush; old-2 has one attempt left before dead-lettering
    send.script = undefined; // not used below
    online = true;
    const failingSend = createQueue({
      send: vi.fn(async (m) => {
        if (m.op === 'old-2') throw new Error('nope');
      }),
      storage,
      isOnline: () => true,
    });
    void failingSend;

    await q.goingOnline();
    expect(send.mock.calls.map((c) => c[0].op)).toEqual(['old-1', 'old-2', 'new']);
    expect(q.pending()).toHaveLength(0);
  });

  it('flush does nothing while offline even if called explicitly', async () => {
    const send = scriptableSend(['ok']);
    const q = createQueue({ send, storage: makeStorage(), isOnline: () => false });
    await q.enqueue({ op: 'held' });
    await q.flush();
    expect(send).not.toHaveBeenCalled();
    expect(q.pending()).toHaveLength(1);
  });
});
"})
